            new("GetBucketCors", OperationStatus.Unsupported, new[] { "Azure: (no equivalent — proxy returns 404 NoSuchCORSConfiguration)", "Diff: GET returns HTTP 404 with code NoSuchCORSConfiguration so clients receive the same shape as a never-configured S3 bucket instead of InternalError." }),
            new("GetBucketEncryption", OperationStatus.Partial, new[] { "Azure: Container metadata for SSE-S3 intent; Azure Storage encryption remains account-managed", "Diff: AES256 is compatibility intent only. Azure encrypts data at rest according to storage-account settings, not this metadata value.", "Diff: When no explicit intent is stored, the response reports the AWS default SSE-S3 AES256 configuration." }),
            new("GetBucketLifecycleConfiguration", OperationStatus.Unsupported, new[] { "Azure: (no equivalent — proxy returns 404 NoSuchLifecycleConfiguration)", "Diff: GET returns HTTP 404 with code NoSuchLifecycleConfiguration so clients receive the same shape as a never-configured S3 bucket instead of InternalError." }),
            new("GetBucketLogging", OperationStatus.Stub, new[] { "Azure: (no equivalent — proxy returns an empty <BucketLoggingStatus/> document)", "Diff: GET returns 200 with an empty <BucketLoggingStatus/> document, matching the S3 'never configured' wire shape." }),
