            new("GetBucketOwnershipControls", OperationStatus.Partial, new[] { "Azure: Container metadata (persisted compatibility intent only)", "Diff: A missing intent returns 404 OwnershipControlsNotFoundError. A present intent is not an Azure authorization control." }),
            new("GetBucketPolicy", OperationStatus.Unsupported, new[] { "Azure: (no equivalent — proxy returns 404 NoSuchBucketPolicy)", "Diff: GET returns HTTP 404 with code NoSuchBucketPolicy so clients receive the same shape as a never-configured S3 bucket instead of InternalError." }),
            new("GetBucketPolicyStatus", OperationStatus.Unsupported, new[] { "Azure: (no equivalent — proxy returns 404 NoSuchBucketPolicy)", "Diff: GET returns HTTP 404 with code NoSuchBucketPolicy so clients receive the same shape as a never-configured S3 bucket instead of InternalError." }),
            new("GetBucketReplication", OperationStatus.Unsupported, new[] { "Azure: (no equivalent — proxy returns 404 ReplicationConfigurationNotFoundError)", "Diff: GET returns HTTP 404 with code ReplicationConfigurationNotFoundError so clients receive the same shape as a never-configured S3 bucket instead of InternalError." }),
            new("GetBucketRequestPayment", OperationStatus.Partial, new[] { "Azure: (no equivalent — proxy returns the S3 default body)", "Diff: GET deterministically returns 200 with <Payer>BucketOwner</Payer>; Requester Pays is never activated." }),
            new("GetBucketTagging", OperationStatus.Partial, new[] { "Azure: GET {container}?restype=container&comp=metadata (single opaque metadata blob)", "Diff: Bucket tags survive process restarts because they live on the container metadata, but they are invisible to any Azure-native tooling that does not know about the aws2azurebuckettags key." }),
            new("GetBucketVersioning", OperationStatus.Partial, new[] { "Azure: Container metadata (per-bucket toggle); reflects stored PutBucketVersioning intent", "Diff: GET returns the per-bucket toggle persisted by PutBucketVersioning. Azure Blob versioning itself is account-scoped: actual version retention requires account-level versioning enabled out-of-band by the operator.", "Diff: MFADelete is never reported (not supported)." }),
            new("GetBucketWebsite", OperationStatus.Unsupported, new[] { "Azure: (no equivalent — proxy returns 404 NoSuchWebsiteConfiguration)", "Diff: GET returns HTTP 404 with code NoSuchWebsiteConfiguration so clients receive the same shape as a never-configured S3 bucket instead of InternalError." }),
            new("GetObject", OperationStatus.Implemented, new[] { "Azure: GET https://{account}.blob.core.windows.net/{container}/{blob}", "Diff: Streaming end-to-end: response body is forwarded without buffering.", "Diff: x-amz-id-2 carries the Azure x-ms-request-id for cross-system tracing.", "Diff: The default object Content-Type when Azure has none is binary/octet-stream to match observed S3 behavior.", "Diff: x-amz-server-side-encryption is synthesized as AES256 to reflect Azure Storage's at-rest encryption baseline.", "Diff: x-amz-checksum-crc64nvme is not emitted; Azure does not expose AWS's CRC64NVME checksum surface on GetObject responses.", "Diff: Presigned URLs are accepted (see PresignedUrl.yaml); the client must sign against the proxy host.", "Diff: Error responses omit the server-side x-amz-id-2 correlation header that real S3 emits. [conformance:missing-header:x-amz-id-2]", "Diff: Error envelopes omit the <HostId> element that real S3 emits. [conformance:missing-field:HostId]", "Diff: NoSuchBucket envelopes omit the informational <BucketName> element real S3 includes. [conformance:nosuchbucket-get-object::missing-field:BucketName]", "Diff: NoSuchKey envelopes omit the informational <Key> element real S3 includes. [conformance:nosuchkey-get-object::missing-field:Key]", "Diff: PreconditionFailed envelopes omit the informational <Condition> element (e.g. <Condition>If-Match</Condition>) real S3 includes. [conformance:precondition-failed-get::missing-field:Condition]" }),
            new("GetObjectAcl", OperationStatus.Partial, new[] { "Azure: (no Azure equivalent — synthetic ownership-only response)", "Diff: The versionId selects the object existence check, but ACL grants remain synthetic owner-only state.", "Diff: Azure BlobVersionNotFound maps to S3 NoSuchVersion." }),
            new("GetObjectLegalHold", OperationStatus.Implemented, new[] { "Azure: Blob legal hold (HEAD blob: x-ms-legal-hold)", "Diff: Verified against real Azure only - Azurite does not support legal hold." }),
            new("GetObjectLockConfiguration", OperationStatus.Unsupported, new[] { "Azure: (bucket-level WORM is ARM/management-plane only; proxy returns 404 ObjectLockConfigurationNotFoundError)", "Diff: GET returns HTTP 404 with code ObjectLockConfigurationNotFoundError so clients receive the same shape as a never-configured S3 bucket instead of InternalError." }),
            new("GetObjectRetention", OperationStatus.Implemented, new[] { "Azure: Blob immutability policy (HEAD blob: x-ms-immutability-policy-mode/-until-date)", "Diff: Mode mapping: GOVERNANCE<->unlocked, COMPLIANCE<->locked. Azure locked is irreversible and extend-only, like S3 COMPLIANCE.", "Diff: Verified against real Azure only - Azurite does not support immutability policies." }),
            new("GetObjectTagging", OperationStatus.Implemented, new[] { "Azure: GET {blob}?comp=tags (Azure Blob Index Tags)", "Diff: Returns an empty TagSet (200) when no tags are set, matching Azure's behaviour. Azure surfaces 'no tags' as an empty set rather than a NoSuchTagSet error.", "Diff: Version selection depends on Azure Blob versioning being enabled by the operator.", "Diff: Azure BlobVersionNotFound maps to S3 NoSuchVersion." }),
