            new("HeadBucket", OperationStatus.Implemented, new[] { "Azure: HEAD https://{account}.blob.core.windows.net/{container}?restype=container", "Diff: 404 responses include x-amz-error-code: NoSuchBucket so SDKs can map the error without a body (HEAD has none)." }),
            new("HeadObject", OperationStatus.Implemented, new[] { "Azure: HEAD https://{account}.blob.core.windows.net/{container}/{blob}", "Diff: 404 responses include x-amz-error-code: NoSuchKey and an empty body (HEAD spec).", "Diff: 412 PreconditionFailed (failed If-Match) responses include x-amz-error-code: PreconditionFailed and an empty body (HEAD spec).", "Diff: Presigned HEAD is accepted (see PresignedUrl.yaml)." }),
