            new("ListObjects", OperationStatus.Implemented, new[] { "Azure: GET https://{account}.blob.core.windows.net/{container}?restype=container&comp=list", "Diff: Legacy V1 listing kept alongside V2 for SDKs that have not migrated.", "Diff: Without a delimiter, callers derive the next marker from the last Contents.Key (matches S3 docs)." }),
            new("ListObjectsV2", OperationStatus.Implemented, new[] { "Azure: GET https://{account}.blob.core.windows.net/{container}?restype=container&comp=list", "Diff: Pagination is server-driven against Azure; the proxy paginates internally to fill max-keys.", "Diff: Blob storage is flat — delimiter-based grouping is computed by Azure and surfaced as CommonPrefixes.", "Diff: CommonPrefixes are de-duplicated across Azure pages.", "Diff: NextContinuationToken / ContinuationToken use a proxy-defined opaque encoding of Azure's marker rather than AWS's token format; clients must treat them as opaque. [conformance:list-objects-v2-pagination::field-value:NextContinuationToken] [conformance:list-objects-v2-pagination::field-value:ContinuationToken]", "Diff: Offline Tier-3 real-AWS vs real-Azure diffs normalize the echoed bucket Name field when captures were recorded against different ephemeral bucket names for the same case. [conformance:list-objects-v2-pagination::field-value:Name]" }),
            new("ListParts", OperationStatus.Implemented, new[] { "Azure: Proxy state HEAD/verification + Get Block List (?comp=blocklist&blocklisttype=uncommitted)", "Diff: <ETag> values returned by ListParts are synthetic (derived from the Azure block name) and are NOT equal to the per-part ETags returned by UploadPart. Azure's Get Block List response does not expose per-block MD5s, so this permanent incompatibility remains explicit.", "Diff: <LastModified> for every part is the multipart upload's initiation timestamp from the durable state record; Azure exposes no per-block timestamp.", "Diff: <Owner> / <Initiator> are omitted because aws2azure does not model IAM principals." }),
            new("PresignedUrl", OperationStatus.Implemented, new[] { "Azure: (no operation — feature-flag; presigned URLs reuse GetObject / PutObject / HeadObject / DeleteObject paths)", "Diff: By default (empty s3.presignedTrustedSigningHosts) presigned URLs MUST be signed against the proxy host (set the AWS SDK's endpoint_url / ServiceURL to the proxy). A URL signed against s3.amazonaws.com cannot be replayed at the proxy — the host is a signed header.", "Diff: Opt-in host-rewrite mode (s3.presignedTrustedSigningHosts) additionally accepts presigned URLs signed against listed AWS origin hosts and rewritten to a path-style proxy request; see docs/presigned-urls.md for the per-topology tradeoffs.", "Diff: The proxy operates in 'Option A — proxy mode': it validates the presigned signature, then proxies the operation to Azure Blob using its configured Azure credentials. No Azure SAS is returned or redirected.", "Diff: Body content for presigned PUT is not signature-protected (UNSIGNED-PAYLOAD) — identical to AWS S3 semantics.", "Diff: Tampering with any signed query parameter (including X-Amz-Date, X-Amz-Expires, X-Amz-Credential, X-Amz-SignedHeaders, or the path/method) yields 403 SignatureDoesNotMatch.", "Diff: Expired URLs (now > X-Amz-Date + X-Amz-Expires) yield 403 AccessDenied (mirrors S3's 'Request has expired' error)." }),
